const VERSION="v9",SCOPE=new URL("./",self.location).pathname,BYPASS_DIRS=["play","next","game","assets/js/world"].map(e=>SCOPE+e),BYPASS_FILE=/\.(?:glb|wasm|ktx2|mp3|ogg)$/i;function isBypassed(e){return e.startsWith(SCOPE)?BYPASS_DIRS.some(t=>e===t||e.startsWith(t+"/"))||e.slice(SCOPE.length).startsWith("asset-manifest.")?!0:BYPASS_FILE.test(e):!1}const PRECACHE="precache-v9",RUNTIME="runtime-v9",PRECACHE_URLS=["./","./index.html","./assets/styles/main.css","./assets/js/boot.min.js","./assets/fonts/schibsted-grotesk.woff2","./assets/fonts/jetbrains-mono.woff2","./assets/brand/mark-duo.svg","./manifest.json"];self.addEventListener("install",e=>{e.waitUntil(caches.open(PRECACHE).then(t=>t.addAll(PRECACHE_URLS)).then(()=>self.skipWaiting()))}),self.addEventListener("activate",e=>{const t=[PRECACHE,RUNTIME];e.waitUntil(caches.keys().then(r=>{const s=r.filter(n=>!t.includes(n));return Promise.all(s.map(n=>caches.delete(n))).then(()=>s.length)}).then(r=>self.clients.claim().then(()=>{if(r)return self.clients.matchAll({type:"window"}).then(s=>Promise.all(s.map(n=>{if(!isBypassed(new URL(n.url).pathname))return n.navigate(n.url).catch(()=>{})})))})))}),self.addEventListener("fetch",e=>{const t=e.request;if(t.method!=="GET")return;const r=new URL(t.url);if(r.origin===self.location.origin&&!isBypassed(r.pathname)){if(t.mode==="navigate"){e.respondWith(fetch(t).then(s=>{if(s.ok){const n=s.clone();caches.open(RUNTIME).then(a=>a.put(t,n))}return s}).catch(()=>caches.match(t).then(s=>s||caches.match("./index.html"))));return}e.respondWith(caches.match(t).then(s=>{const n=fetch(t).then(a=>{if(a.ok){const c=a.clone();caches.open(RUNTIME).then(i=>i.put(t,c))}return a}).catch(()=>s);return s||n}))}});
